inner_query = {
    "query": {
        "prefix": {
            "response": "5"
        }
    }
}
es_query_str = json.dumps(inner_query)

Now params dict:

{
  "searchType": "esQuery",
  "esQuery": es_query_str,
  "index": ["kibana_sample_data_logs"],
  "timeField": "timestamp",
  "threshold": [10],
  "thresholdComparator": ">",
  "timeWindowSize": 5,
  "timeWindowUnit": "m",
  "size": 100
}

